		getFirstForwardedValue(headers.get('x-forwarded-proto') ?? undefined),
		getFirstForwardedValue(headers.get('x-forwarded-host') ?? undefined),
		getFirstForwardedValue(headers.get('x-forwarded-port') ?? undefined),
		allowedDomains,
	);

