function webToCachePolicyRequest({ url, method, headers }: Request): CachePolicy.Request {
	return {
		method,
		url,
		headers: Object.fromEntries(headers.entries()),
	};
}

function webToCachePolicyResponse({ status, headers }: Response): CachePolicy.Response {
	return {
		status,
		headers: Object.fromEntries(headers.entries()),
	};
}

