pub(crate) fn replace_all<'a>(
    &'a mut self,
    searcher: &Searcher,
    matcher: &M,
    mut haystack: &[u8],
    range: std::ops::Range<usize>,
    replacement: &[u8],
) -> io::Result<()> {
